style.css:
@-moz-document domain("tiktok.com") {
/* Hide video progress bar */
  .tiktok-1s0gnbu-DivSeekBarContainer,
  .tiktok-1h6pbn9-DivSeekBar,
  .tiktok-pxoysp-DivSeekBarPointer {
    display: none !important;
  }

  /* Hide comments section */
  .tiktok-1ttdu2b-DivCommentContainer {
    display: none !important;
  }

  /* Optional: Hide the description, likes, and share button */
  .tiktok-xn73dw-DivActionBar,
  .tiktok-1qa1otp-DivContainer,
  .tiktok-1c3fd3m-PDivText {
    display: none !important;
  }
}
